extern "C" void * __cdecl memset(void *, int, unsigned int);
extern "C" void * __cdecl memcpy(void *, const void *, unsigned int);
#pragma intrinsic(memset)
#pragma intrinsic(memcpy)

struct Rva009A8C50Context
{
	unsigned char m_pad0[0x78];
	unsigned char *m_plane0;
	unsigned char *m_plane1;
	unsigned char *m_plane2;
	unsigned char m_pad1[0x90 - 0x84];
	int m_rows;
	int m_columns;
	int m_stride0;
	int m_stride1;
	unsigned char m_pad2[0xB4 - 0xA0];
	int m_border;
};

extern "C" void Rva009A8C50CopyPlanes(Rva009A8C50Context *self, int offset)
{
	unsigned char *plane0 = self->m_plane0;
	unsigned char *plane1 = self->m_plane1;
	unsigned char *plane2 = self->m_plane2;
	int rows = self->m_rows;
	int columns = self->m_columns;
	int stride0 = self->m_stride0;
	int stride1 = self->m_stride1;
	int border = self->m_border;
	unsigned char *line = plane0 + offset;
	for (int row = 0; row < rows; ++row)
	{
		memset(line - border, line[0], border);
		memset(line + columns * 8, line[columns * 8 - 1], border);
		line += stride0;
	}

	unsigned char *top = plane0 + offset;
	unsigned char *topSource = top + border * stride0;
	unsigned char *bottomSource = topSource + (columns * 8 - 1) * stride0;
	unsigned char *bottom = top + (border + columns * 8) * stride0;
	for (int row = 0; row < border; ++row)
	{
		memcpy(top, topSource, stride0);
		memcpy(bottom, bottomSource, stride0);
		top += stride0;
		bottom += stride0;
	}

	int halfBorder = border >> 1;
	line = plane1 + offset;
	for (int row = 0; row < columns * 4; ++row)
	{
		memset(line - halfBorder, line[0], halfBorder);
		memset(line + rows * 4, line[rows * 4 - 1], halfBorder);
		line += stride1;
	}

	top = plane1 + offset - halfBorder;
	topSource = top + halfBorder * stride1;
	bottomSource = topSource + (columns * 4 - 1) * stride1;
	bottom = top + (halfBorder + columns * 4) * stride1;
	for (int row = 0; row < halfBorder; ++row)
	{
		memcpy(top, topSource, stride1);
		memcpy(bottom, bottomSource, stride1);
		top += stride1;
		bottom += stride1;
	}

	line = plane2 + offset;
	for (int row = 0; row < columns * 4; ++row)
	{
		memset(line - halfBorder, line[0], halfBorder);
		memset(line + rows * 4, line[rows * 4 - 1], halfBorder);
		line += stride1;
	}

	top = plane2 + offset - halfBorder;
	topSource = top + halfBorder * stride1;
	bottomSource = topSource + (columns * 4 - 1) * stride1;
	bottom = top + (halfBorder + columns * 4) * stride1;
	for (int row = 0; row < halfBorder; ++row)
	{
		memcpy(top, topSource, stride1);
		memcpy(bottom, bottomSource, stride1);
		top += stride1;
		bottom += stride1;
	}
}
